import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>

using namespace cute;

#define WARP_SIZE 32
#define MAX_EPT 32  // supports head-dim (D) up to WARP_SIZE * MAX_EPT = 1024

__global__ void flash_attn_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ O,
    int BH, int S, int D, float scale, int warps_per_block)
{
    extern __shared__ unsigned char smem_raw[];
    half* sK = reinterpret_cast<half*>(smem_raw);
    half* sV = sK + D;

    int bh      = blockIdx.x;
    int lane    = threadIdx.x;
    int warp_id = threadIdx.y;
    int q_row   = blockIdx.y * warps_per_block + warp_id;

    const half* Qb = Q + (int64_t)bh * (int64_t)S * D;
    const half* Kb = K + (int64_t)bh * (int64_t)S * D;
    const half* Vb = V + (int64_t)bh * (int64_t)S * D;
    half*       Ob = O + (int64_t)bh * (int64_t)S * D;

    // CUTE tensors over the (S, D) slice for this (batch, head)
    auto mQ = make_tensor(make_gmem_ptr(Qb), make_shape(S, D), make_stride(D, 1));
    auto mK = make_tensor(make_gmem_ptr(Kb), make_shape(S, D), make_stride(D, 1));
    auto mV = make_tensor(make_gmem_ptr(Vb), make_shape(S, D), make_stride(D, 1));
    auto mO = make_tensor(make_gmem_ptr(Ob), make_shape(S, D), make_stride(D, 1));

    int ept = D / WARP_SIZE;

    float q_reg[MAX_EPT];
    float o_reg[MAX_EPT];

    bool valid = (q_row < S);

    #pragma unroll
    for (int i = 0; i < MAX_EPT; ++i) {
        if (i < ept) {
            int d = i * WARP_SIZE + lane;
            q_reg[i] = valid ? __half2float(mQ(q_row, d)) : 0.0f;
            o_reg[i] = 0.0f;
        }
    }

    float running_max = -INFINITY;
    float running_sum = 0.0f;

    int tid_in_block  = warp_id * WARP_SIZE + lane;
    int block_threads = warps_per_block * WARP_SIZE;

    for (int j = 0; j < S; ++j) {
        // Cooperative load of K[j,:] and V[j,:] into shared memory
        for (int idx = tid_in_block; idx < D; idx += block_threads) {
            sK[idx] = mK(j, idx);
            sV[idx] = mV(j, idx);
        }
        __syncthreads();

        float partial = 0.0f;
        #pragma unroll
        for (int i = 0; i < MAX_EPT; ++i) {
            if (i < ept) {
                int d = i * WARP_SIZE + lane;
                partial += q_reg[i] * __half2float(sK[d]);
            }
        }

        // Warp-wide reduction (butterfly) -> every lane gets full dot product
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            partial += __shfl_xor_sync(0xFFFFFFFF, partial, offset);
        }

        if (valid) {
            float score = partial * scale;
            float new_max = fmaxf(running_max, score);
            float correction = expf(running_max - new_max);
            float p = expf(score - new_max);
            running_sum = running_sum * correction + p;

            #pragma unroll
            for (int i = 0; i < MAX_EPT; ++i) {
                if (i < ept) {
                    int d = i * WARP_SIZE + lane;
                    o_reg[i] = o_reg[i] * correction + p * __half2float(sV[d]);
                }
            }
            running_max = new_max;
        }

        __syncthreads();
    }

    if (valid) {
        float inv_sum = (running_sum > 0.0f) ? (1.0f / running_sum) : 0.0f;
        #pragma unroll
        for (int i = 0; i < MAX_EPT; ++i) {
            if (i < ept) {
                int d = i * WARP_SIZE + lane;
                mO(q_row, d) = __float2half(o_reg[i] * inv_sum);
            }
        }
    }
}

torch::Tensor attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Q, K, V must be float16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be [B,H,S,D]");

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int S = (int)Qc.size(2);
    int D = (int)Qc.size(3);

    TORCH_CHECK(K.size(2) == S && K.size(3) == D, "K shape mismatch");
    TORCH_CHECK(V.size(2) == S && V.size(3) == D, "V shape mismatch");

    TORCH_CHECK(D % WARP_SIZE == 0, "D must be divisible by 32");
    TORCH_CHECK(D / WARP_SIZE <= MAX_EPT, "D too large for this kernel");

    auto O = torch::empty_like(Qc);

    int BH = B * H;
    int warps_per_block = 8;
    dim3 block(WARP_SIZE, warps_per_block, 1);
    dim3 grid((unsigned)BH, (unsigned)((S + warps_per_block - 1) / warps_per_block), 1);

    size_t smem_bytes = 2 * (size_t)D * sizeof(half);

    float scale = 1.0f / sqrtf((float)D);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    flash_attn_kernel<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        BH, S, D, scale, warps_per_block
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "flash_attn_kernel launch failed: ", cudaGetErrorString(err));

    return O;
}
"""

attn_ext = load_inline(
    name="cute_flash_attention_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["attention_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = attn_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.attention_forward(Q, K, V)

