import math
import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX flash-attention kernel (sm_89 / Ada, RTX 4090).
#
# Semantics mirror the CuTe/CUDA reference implementation:
#   - one warp computes one query row (q_row) of the (S, D) slice for a
#     given (batch, head) pair (bh = blockIdx.x)
#   - K/V rows are cooperatively staged into dynamic shared memory per
#     iteration j over the sequence dimension S
#   - online (flash) softmax accumulation is performed in registers /
#     thread-local memory, one float accumulator per element-per-thread
#     (ept = D / 32) slot
#   - final output row is normalized and written back as fp16
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.extern .shared .align 16 .b8 smem_raw[];

.visible .entry flash_attn_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 O_ptr,
    .param .u32 BH,
    .param .u32 S,
    .param .u32 D,
    .param .f32 scale,
    .param .u32 warps_per_block
)
{
    .reg .pred %p<20>;
    .reg .b16 %rs<10>;
    .reg .b32 %r<100>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<40>;

    .local .align 4 .b8 q_local[128];
    .local .align 4 .b8 o_local[128];

    ld.param.u64 %rd1, [Q_ptr];
    ld.param.u64 %rd2, [K_ptr];
    ld.param.u64 %rd3, [V_ptr];
